// New variations are reviewed templates with compatible slots, not unrestricted sentence generation.
const people=[['tanaka','{田中|たなか}さん','田中'],['hayashi','{林|りん}さん','林'],['sato','{佐藤|さとう}さん','佐藤']];
const actions=[['come','{来|き}ます','要來'],['sing','{歌|うた}います','要唱歌'],['read','{本|ほん}を{読|よ}みます','要讀書']];
const interests=[['music','{音楽|おんがく}','音樂'],['cooking','{料理|りょうり}','做菜'],['swimming','{水泳|すいえい}','游泳']];
const predicates=[['like','{好|す}きです','喜歡'],['good','{上手|じょうず}です','擅長'],['notlike','{好|す}きじゃないです','不喜歡']];
const travel=[['park','{公園|こうえん}に{行|い}きます','去公園'],['tea','お{茶|ちゃ}を{飲|の}みます','喝茶'],['movie','{映画|えいが}を{見|み}ます','看電影']];
const pairs=[['bread-milk','パン','{牛乳|ぎゅうにゅう}','麵包','牛奶'],['apple-banana','りんご','バナナ','蘋果','香蕉'],['tea-water','お{茶|ちゃ}','{水|みず}','茶','水']];
const shopping=[['buy','{買|か}います','買'],['bring','{持|も}って{行|い}きます','帶去'],['prepare','{用意|ようい}します','準備']];
export const connectionVariations=[];
function add(id,lesson,use,context,sentence,translation,why,options,answer,words){
 const wrong=Object.fromEntries(options.filter(x=>x!==answer).map(x=>[x,x==='は'||x==='が'?'這個助詞可能出現在其他語境；本題要依指定的提問重點與句型選擇。':'這裡要標出題目指定的關係，請對照完整答案與說明。']));
 connectionVariations.push({...q('v2:'+id,use,context,sentence,options,[answer],why,wrong),lesson,translation,words:words.map(([id,jp,zh])=>({id,jp,zh})),generated:true});
}
for(const a of people)for(const v of actions){
 add('ga-person:'+a[0]+':'+v[0],'ga','ga-subject',`對方問誰${v[2]}，本題用が直接指出${a[2]}。`,`${a[1]}＿${v[1]}。`,`${a[2]}${v[2]}。`,'が標出這個動作的人。',['が','を','で'],'が',[a,v]);
 add('wg-focus:'+a[0]+':'+v[0],'wa-ga','wa-ga-context',`回答「誰が${v[1].replace(/\{([^|}]+)\|[^}]+\}/g,'$1')}か」。本題要直接補回誰的焦點，選最符合此目的的標記。`,`${a[1]}＿${v[1]}。`,`${a[2]}${v[2]}。`,'直接回答誰，用が指出人名；は在其他語境可提出話題或對比。',['が','は','を'],'が',[a,v]);
 add('wg-topic:'+a[0]+':'+v[0],'wa-ga','wa-ga-context',`目前已在談${a[2]}。請用は提出話題，詢問${a[2]}是否${v[2]}。`,`${a[1]}＿${v[1]}か。`,`${a[2]}${v[2]}嗎？`,'本題指定用は維持話題，再問後面的行動。',['は','が','を'],'は',[a,v]);
}
for(const interest of interests)for(const v of predicates){
 // For skill, use a concrete performance activity rather than the broad category 音楽.
 const a=interest[0]==='music'&&v[0]==='good'?['piano','ピアノ','彈鋼琴']:interest;
 add('ga-interest:'+a[0]+':'+v[0],'ga','ga-target',`用本課基本句型說「${v[2]}${a[2]}」。`,`${a[1]}＿${v[1]}。`,`${v[2]}${a[2]}。`,'好き、上手等基本句型以が標出對象。',['が','を','の'],'が',[a,v]);
}
for(const a of people)for(const v of travel)add('to-partner:'+a[0]+':'+v[0],'to','to-partner',`你和${a[2]}一起${v[2]}，請標記同伴。`,`{私|わたし}は${a[1]}＿${v[1]}。`,`我和${a[2]}一起${v[2]}。`,'同伴後用と，其他助詞保留原本的工作。',['と','に','を'],'と',[a,v]);
for(const a of pairs)for(const v of shopping)add('to-list:'+a[0]+':'+v[0],'to','to-list',`這次要${v[2]}的兩樣是${a[3]}與${a[4]}，請完整列出兩項。`,`${a[1]}＿${a[2]}を${v[1]}。`,`${v[2]}${a[3]}與${a[4]}。`,'と連起兩個名詞，最後的を標整組動作對象。',['と','の','で'],'と',[[a[0]+'a',a[1],a[3]],[a[0]+'b',a[2],a[4]],v]);
